import{_ as e,o as r,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-07-23","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-07-23","date":"2025-07-23T00:00:00.000Z","updated":"2025-07-24T00:00:00.000Z","tags":["Ceph","RGW","安全加密","存储架构","KMS 集成"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-07-23.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-07-23.md","lastUpdated":1780460162000}'),n={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-07-23.md"};function s(i,t,l,c,g,p){return r(),a("div",null,[...t[0]||(t[0]=[o('<h3 id="ceph-社区会议纪要-ss3-kms-集成与加密对象拷贝问题" tabindex="-1"><strong>Ceph 社区会议纪要 - SS3/KMS 集成与加密对象拷贝问题</strong> <a class="header-anchor" href="#ceph-社区会议纪要-ss3-kms-集成与加密对象拷贝问题" aria-label="Permalink to &quot;**Ceph 社区会议纪要 - SS3/KMS 集成与加密对象拷贝问题**&quot;">​</a></h3><h4 id="日期-2025-07-23-参会人员-boris-marcus-cena-等" tabindex="-1"><strong>日期</strong>: 2025-07-23 | <strong>参会人员</strong>: Boris, Marcus, Cena 等 <a class="header-anchor" href="#日期-2025-07-23-参会人员-boris-marcus-cena-等" aria-label="Permalink to &quot;**日期**: 2025-07-23 | **参会人员**: Boris, Marcus, Cena 等&quot;">​</a></h4><h3 id="_1-主要议题与讨论" tabindex="-1"><strong>1. 主要议题与讨论</strong> <a class="header-anchor" href="#_1-主要议题与讨论" aria-label="Permalink to &quot;**1. 主要议题与讨论**&quot;">​</a></h3><h4 id="_1-ss3-与-kms-密钥管理系统-集成问题" tabindex="-1"><strong>(1) SS3 与 KMS（密钥管理系统）集成问题</strong> <a class="header-anchor" href="#_1-ss3-与-kms-密钥管理系统-集成问题" aria-label="Permalink to &quot;**(1) SS3 与 KMS（密钥管理系统）集成问题**&quot;">​</a></h4><ul><li><strong>问题背景</strong>: 由于当前使用的 OVH KMS 系统不支持 transit engine，需通过 KMIP 或 key-value engine 实现与 SS3 的集成。</li><li><strong>技术可行性</strong>: Ceph 代码库不支持非 Vault 的 KMS 后端，需开发新功能。KMIP 支持需升级以支持类似 Vault transit 的加密模式。</li><li><strong>替代方案讨论</strong>: 探索 IBM/OVH 提供的 KMS API 或开源 KMIP 实现，如 <code>open-pkcs11</code>。</li><li><strong>后续行动</strong>: Boris 将尝试联系 OVH 获取 KMS 实例，社区将创建 Feature Tracker 标记此需求。</li></ul><h4 id="_2-加密对象拷贝-copy-encrypted-object-问题" tabindex="-1"><strong>(2) 加密对象拷贝（Copy Encrypted Object）问题</strong> <a class="header-anchor" href="#_2-加密对象拷贝-copy-encrypted-object-问题" aria-label="Permalink to &quot;**(2) 加密对象拷贝（Copy Encrypted Object）问题**&quot;">​</a></h4><ul><li><strong>问题描述</strong>: 当前 Ceph 中，加密对象的拷贝和移动操作失败，原因是拷贝响应中缺少必要的加密元数据。</li><li><strong>技术细节</strong>: AWS S3 规范要求拷贝操作需返回与源对象相同的加密头。</li><li><strong>下一步计划</strong>: Marcus 将修复 multipart upload 的加密属性传递问题，并重新测试。</li></ul><h3 id="_2-关键结论与行动计划" tabindex="-1"><strong>2. 关键结论与行动计划</strong> <a class="header-anchor" href="#_2-关键结论与行动计划" aria-label="Permalink to &quot;**2. 关键结论与行动计划**&quot;">​</a></h3><p>| <strong>事项</strong> | <strong>负责人</strong> | <strong>下一步行动</strong> |<br> |||--|<br> | SS3 支持非 Vault KMS | Boris | 联系 OVH 获取 KMS 实例；评估 OpenBao 代理方案的可行性。 |<br> | 改进 Ceph KMIP 支持 | 社区 | 创建 Feature Tracker；评估代码修改范围，优先支持 transit-like 模式。 |<br> | 加密对象拷贝修复 | Marcus | 修复 multipart upload 的加密属性传递问题，重新提交 PR 并通过测试。 |</p><h3 id="_3-其他备注" tabindex="-1"><strong>3. 其他备注</strong> <a class="header-anchor" href="#_3-其他备注" aria-label="Permalink to &quot;**3. 其他备注**&quot;">​</a></h3><ul><li>关键术语保留英文（如 KMIP、transit engine、multipart upload、SSE-S3/KMS）。</li><li>下次会议将跟进 KMS 集成进展和加密拷贝问题的修复状态。</li></ul><p><strong>会议结束时间</strong>: [需补充] | <strong>下次会议时间</strong>- [需补充]</p>',12)])])}const _=e(n,[["render",s]]);export{d as __pageData,_ as default};
